#[derive(Debug, Default, PartialEq, Eq)]
struct Expression {
    names: Vec<NameTest>,
    kinds: Vec<Kind>,
    max_depth: Option<u32>,
    sizes: Vec<SizeTest>,
    ages: Vec<AgeTest>,
    /// `-delete`, the last word.
    delete: bool,
    /// `-y`: the question `-delete` asks is skipped.
    yes: bool,
    json: bool,
