    assert!(retried.status.success(), "{}", text(&retried.stderr));
    assert_eq!(fs::read(dst.join("own.txt")).unwrap(), b"the whole file");
    assert_eq!(fs::read(dst.join("kept.txt")).unwrap(), b"mine");
