/// This machine's run records: `<per-user folder>/jobs/runs`.
pub fn runs_dir(config_dir: &Path) -> PathBuf {
    config_dir.join("jobs").join("runs")
}

/// This machine's saved jobs: `<per-user folder>/jobs/saved`.
pub fn saved_dir(config_dir: &Path) -> PathBuf {
    config_dir.join("jobs").join("saved")
}

/// Write the run's spec and its `running` record, the run started at
/// `started_ms`. `None`, with a warning added to `warnings` and why, when
/// either cannot be kept — the command runs regardless. Blocking.
fn begin_record(
    machine: &Machine,
    verb: &str,
    args: &TransferArgs,
    run_id: &str,
    started_ms: u64,
    origin: RunOrigin,
    warnings: &mut Vec<String>,
) -> (Option<Recorded>, Option<String>) {
    let mut unkept = |what: String| {
        warnings.push(format!("blit: warning: this run's job is not kept: {what}"));
        (None, Some(what))
    };
    let spec = match job_spec(verb, args, &machine.id) {
        Ok(spec) => spec,
        Err(what) => return unkept(what),
    };
    let store = RunStore::new(runs_dir(&machine.config_dir));
    let mut record = RunRecord::starting_at(run_id, &spec, started_ms);
    record.saved_job = origin.saved_job;
    if let Some((parent, attempt)) = origin.parent {
        record.parent = Some(parent);
        record.attempt = attempt.saturating_add(1);
    }
    match store.begin(&spec, &record) {
        Ok(live) => (
            Some(Recorded {
                store,
                spec,
                record,
                keep: machine.keep,
                _live: live,
            }),
            None,
        ),
        Err(error) => unkept(format!("{error}")),
    }
}

